/* 1.12 Campus atlas — floating content, restrained botanical details. */
:root{
 --paper:#faf8f2;--ink:#233e33;--muted:#646f65;--green:#284e3d;--line:#dce1d7;--accent:#e7ecdf;
 --font-ui:"Microsoft YaHei UI","PingFang SC",sans-serif;--font-display:"STSong","Songti SC","SimSun",serif;
 --panel-width:352px;--ease:cubic-bezier(.22,1,.36,1);
 /* Embedded original ginkgo-ornament-v1.png; regenerate from the unchanged PNG. */
 --ui-ginkgo:url("data:image/png;base64,");
}
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden}
body{background:#e9e9df;color:var(--ink);font:14px/1.65 var(--font-ui);-webkit-font-smoothing:antialiased}
button,input,select{font:inherit}button{cursor:pointer;color:inherit;border:0;background:none}button:disabled{cursor:wait;opacity:.5}
button{transition:background-color 140ms,color 140ms,transform 140ms var(--ease)}button:active{transform:scale(.98)}
a{color:inherit;text-decoration:none}button,a,input,select,summary{outline-offset:3px}:focus-visible{outline:2px solid var(--green)}
button svg,.ask-symbol svg{width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:1.55;stroke-linecap:round;stroke-linejoin:round;flex-shrink:0}
[hidden]{display:none!important}.sr-only{position:absolute;width:1px;height:1px;clip-path:inset(50%);overflow:hidden}
#stage,#scene{position:absolute;inset:0}#scene canvas{display:block;width:100%;height:100%;touch-action:none}
.masthead{position:absolute;inset:24px 28px auto;z-index:7;display:flex;align-items:center;justify-content:space-between;pointer-events:none}
.masthead>*{pointer-events:auto}.brand{display:flex;align-items:center;gap:12px;font:600 23px/1.4 var(--font-ui);letter-spacing:2px;padding:8px 14px 8px 10px;border-radius:12px;background:#faf8f2ed;border:1px solid #ffffffb0}
.brand-symbol{display:grid;place-items:center;width:42px;height:48px;border:1px solid var(--green);border-radius:16px 16px 4px 4px;background:var(--paper);font:30px var(--font-display)}
.brand small{display:block;font:11px/1.7 var(--font-ui);letter-spacing:.8px;color:var(--muted);margin-top:3px}
.header-actions{display:flex;gap:6px;align-items:center;padding:4px;background:var(--paper);border:1px solid var(--line);border-radius:10px}
.header-actions>button,.settings>summary{min-height:40px;padding:9px 13px;font-size:13px}
.settings{position:relative;margin:0}.settings>summary{cursor:pointer;list-style:none;border-left:1px solid var(--line)}.settings>summary::-webkit-details-marker{display:none}
.settings-body{position:absolute;right:0;top:52px;width:260px;padding:20px;border:1px solid var(--line);background:var(--paper);border-radius:12px;box-shadow:0 12px 32px #233e3320}
.settings-body button{display:block;width:100%;text-align:left;padding:10px 14px;margin:6px 0;border-radius:6px;background:var(--accent)}.settings-body button[aria-pressed=true]{background:var(--green);color:white}.settings-body a{display:block;border-top:1px solid var(--line);padding-top:14px;font-size:13px}
.search-dock{position:absolute;z-index:8;top:24px;left:50%;transform:translateX(-50%);width:min(540px,40vw)}
.ask{display:flex;gap:12px;align-items:center;padding:7px 8px 7px 16px;background:var(--paper);border:1px solid #c9d2c5;border-radius:12px;box-shadow:0 5px 18px #233e3310}
.ask:focus-within{border-color:var(--green);box-shadow:0 0 0 3px #284e3d16}.ask-symbol{display:flex}.ask input{border:0;background:none;outline:none;min-width:0;width:100%;height:38px;color:var(--ink);font-size:14px}.ask input::placeholder{color:var(--muted)}
.ask button{width:38px;height:38px;display:grid;place-items:center;flex-shrink:0;background:var(--green);color:var(--paper);border-radius:8px}.ask #ask-stop{width:46px;font-size:13px;background:#754938}
#categories{position:absolute;z-index:5;left:24px;top:118px;display:flex;flex-direction:column;gap:4px;width:66px;padding:6px;background:var(--paper);border:1px solid var(--line);border-radius:15px;max-height:calc(100dvh - 216px);overflow:auto;scrollbar-width:thin}
#categories button{min-height:60px;flex-shrink:0;display:flex;flex-direction:column;gap:4px;align-items:center;justify-content:center;border-radius:10px;font-size:12px;color:var(--green)}#categories button svg{width:22px;height:22px}
#categories button[aria-pressed=true]{background:var(--green);color:var(--paper)}
.intro,.panel{position:absolute;z-index:6;left:108px;top:118px;width:var(--panel-width);background:var(--paper);border:1px solid #ffffffb0;border-radius:16px;box-shadow:0 10px 34px #213b3212;overflow:hidden}
.intro{padding:28px 26px;transition:opacity 130ms,transform 180ms var(--ease)}.intro:before{content:"";position:absolute;inset:0;background:url('/explore/art/paper-plaster-v1.png') center/300px;opacity:.06;pointer-events:none}.intro[data-hidden=true]{opacity:0;transform:translateX(-8px);visibility:hidden;pointer-events:none}
.eyebrow{font-size:12px;font-weight:500;color:var(--muted);letter-spacing:.8px;margin:0 0 12px}
.intro h1{font:500 32px/1.4 var(--font-display);letter-spacing:2px;margin:0 0 16px}.intro-copy{font-size:14px;color:var(--muted);margin:0;line-height:1.9;position:relative;z-index:1}
.intro-actions{display:flex;gap:16px;align-items:center;margin-top:24px;position:relative;z-index:1}.intro-hint{font-size:12px;color:var(--muted);margin:22px 0 0}
.intro-ornament{position:absolute;right:-5px;bottom:0;width:144px;height:180px;background:var(--ui-ginkgo) right bottom/contain no-repeat;opacity:.25;pointer-events:none}
.panel{display:flex;flex-direction:column;max-height:calc(100dvh - 214px);opacity:0;visibility:hidden;transform:translateX(-10px);transition:transform 200ms var(--ease),opacity 140ms,visibility 140ms}
.panel[data-open=true]{opacity:1;visibility:visible;transform:translateX(0)}.panel[data-open=false]{transition-duration:120ms}
.panel-head{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-shrink:0;padding:22px 24px 18px;border-bottom:1px solid var(--line)}
.panel-head>div:first-child{min-width:0}.panel-head .eyebrow{margin-bottom:7px}.panel-head h2{font:600 25px/1.45 var(--font-ui);letter-spacing:-.4px;margin:0;overflow-wrap:anywhere}
.panel[data-view=building] .panel-head h2{font:600 26px/1.4 var(--font-ui);letter-spacing:0}
.panel-controls{display:flex;gap:4px;flex-shrink:0}.panel-controls button{display:grid;place-items:center;width:32px;height:36px;border-radius:7px;color:var(--muted);background:#edf0e8}.panel-controls svg{width:17px;height:17px}#panel-size{display:none}
#panel-body{padding:20px 24px 22px;overflow:auto;overscroll-behavior:contain;scrollbar-width:thin;scrollbar-color:#bdc8b8 transparent;min-height:0}
.detail-copy{font-size:14px;line-height:1.85;color:#526458;overflow-wrap:anywhere;margin:0 0 18px}.meta{font-size:12px;line-height:1.85;color:var(--muted)}
.building-intro{margin-bottom:22px}.building-section h3{font-size:14px;line-height:1.5;margin:0 0 12px;font-weight:600}
.service-entry{display:flex;align-items:center;gap:12px;width:100%;padding:15px 14px;border:1px solid var(--line);border-radius:9px;background:#eef1e8;text-align:left;margin-top:8px}
.service-entry strong{font-size:14px;font-weight:500}.service-entry span{margin-left:auto;font-size:12px;color:var(--muted)}
.source-details{margin:16px 0 0;border-top:1px solid var(--line);padding-top:10px}.source-details summary{font-size:12px;color:var(--muted);padding:4px 0}
.action{min-height:44px;border-radius:8px;background:var(--green);color:var(--paper);padding:11px 16px;font-size:14px}.action.secondary{background:#e9eee3;color:var(--green);border:1px solid var(--line)}
.text-button{font-size:13px;min-height:40px;padding:8px 0;text-align:left}.action-row{display:flex;gap:14px;align-items:center;margin:20px 0 0}.action-row .action{flex:1}.action-row .text-button{padding:8px}
.finder{width:100%;min-height:44px;border:1px solid var(--line);background:#fffefa;padding:11px 12px;border-radius:8px;font-size:13px;color:var(--ink)}.finder::placeholder{color:var(--muted)}.area-select{margin-top:10px}
.subcategories{display:flex;gap:4px;padding:4px;margin:12px 0 0;background:#edf0e7;border-radius:8px}.subcategories:empty{display:none}.subcategories button{flex:1;padding:7px 3px;font-size:12px;min-height:36px;border-radius:5px;white-space:nowrap}.subcategories button[aria-pressed=true]{background:var(--paper);box-shadow:0 1px 4px #233e3312}
.area-shortcuts{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:12px}.area-shortcuts button{display:flex;flex-direction:column;align-items:flex-start;gap:4px;padding:12px 10px;background:#eef1e7;border:1px solid var(--line);border-radius:8px;font-size:12px;text-align:left}.area-shortcuts strong{font-size:12px;color:var(--green)}.panel[data-area=true] .area-shortcuts{display:none}
.list-summary{font-size:13px;font-weight:600;margin:18px 0 6px}.area-note{font-size:12px;line-height:1.7;color:var(--muted);margin:0 0 8px}
.directory-filters{margin:10px 0}.directory-filters summary{font-size:12px;color:var(--muted);padding:5px 0}
.place-list{display:grid}.place-row{display:flex;align-items:center;gap:12px;min-height:80px;padding:16px 0;text-align:left;width:100%;border-bottom:1px solid var(--line)}
.place-symbol{display:grid;place-items:center;width:36px;height:40px;background:#e9eee1;border-radius:8px;flex-shrink:0}.place-row[data-category=drinks] .place-symbol{color:#846846;background:#eee7dc}
.place-copy{flex:1;min-width:0}.place-copy strong{display:block;font-size:14px;font-weight:600;line-height:1.6}.place-copy small{display:block;font-size:12px;line-height:1.7;color:var(--muted);margin-top:4px}.place-copy .hours-preview{color:var(--green);font-variant-numeric:tabular-nums}
.index-mark{display:none}.arrow{color:#72836c;margin-left:auto}.place-row>strong{font-size:14px;font-weight:500}.pager{padding-top:16px}.load-more{width:100%}
.pill{display:inline-flex;background:#e8eddf;color:#426142;font-size:12px;border-radius:5px;padding:4px 8px}
.info-line{padding:12px 0;border-bottom:1px solid var(--line);font-size:14px;line-height:1.75}.info-line small{display:block;font-size:12px;color:var(--muted);margin-bottom:5px}
.sample-strip{display:flex;flex-wrap:wrap;gap:6px;margin:14px 0}.sample-strip>small{width:100%;font-size:12px;color:var(--muted)}.menu{margin-top:24px}.menu h3{font-size:15px;margin:0}.menu-row{display:flex;justify-content:space-between;gap:12px;padding:12px 0;border-bottom:1px solid var(--line);font-size:14px}.menu-row small{display:block;font-size:12px;color:var(--muted)}.menu-row b{white-space:nowrap;font-size:16px}
.notice{background:#f1ecdf;color:#745f40;border-left:2px solid #a58b62;padding:10px 12px;font-size:13px;line-height:1.8}
details{margin:14px 0}summary{font-size:13px;padding:8px 0;cursor:pointer}.detail-title{font:500 26px/1.5 var(--font-display);margin:18px 0 12px}
.chat-msg{padding:17px 0;border-bottom:1px solid var(--line);font-size:14px;line-height:1.9;white-space:pre-wrap;overflow-wrap:anywhere}.chat-msg.user{background:#e9eee1;padding:13px 15px;border:0;border-radius:10px 10px 2px 10px;margin-top:16px}.chat-msg>small{display:block;font-size:11px;font-weight:600;color:var(--green);margin-bottom:8px}
.chat-result{margin-top:14px;padding:16px;background:#fffef8;border:1px solid var(--line);border-radius:10px;white-space:normal}.chat-result h3{font-size:16px;margin:10px 0}.chat-result p{font-size:13px;line-height:1.8}
.history-row{display:block;width:100%;padding:14px 0;text-align:left;border-bottom:1px solid var(--line);font-size:13px;line-height:1.8}
.condition-form{display:grid;gap:16px}.condition-form label{display:grid;gap:6px;font-size:13px}.condition-form input,.condition-form select{width:100%;min-width:0;min-height:44px;border:1px solid var(--line);border-radius:7px;padding:10px;background:#fffefa;color:var(--ink)}
.side-tools{position:absolute;right:26px;bottom:132px;z-index:4;display:flex;flex-direction:column;gap:4px;padding:5px;background:var(--paper);border:1px solid var(--line);border-radius:12px}.side-tools button{width:38px;height:40px;display:grid;place-items:center;border-radius:7px}
.scene-footer{position:absolute;bottom:24px;left:26px;right:26px;z-index:4;display:flex;align-items:flex-end;justify-content:space-between;pointer-events:none}.scene-footer>*{pointer-events:auto}
.map-note{font-size:11px;line-height:1.6;color:#4c5f51;background:#faf8f2e8;padding:8px 12px;border-radius:7px;max-width:300px}.map-note small{display:block;font-size:10px;color:var(--muted)}
.view-dock{position:absolute;left:50%;bottom:0;transform:translateX(-50%);display:flex;gap:3px;align-items:center;background:var(--paper);padding:6px;border:1px solid var(--line);border-radius:12px;box-shadow:0 4px 20px #213b3212;white-space:nowrap}
.view-dock button{font-size:13px;padding:10px 14px;min-height:42px;border-radius:7px}.view-dock button[aria-pressed=true]{background:var(--green);color:var(--paper)}.divider{width:1px;height:18px;background:var(--line);margin:0 5px}
.footer-right{text-align:right;color:#526458;font-size:8px}.footer-right a{display:block;margin-top:8px}.compass{display:inline-grid;place-items:center;width:34px;height:34px;border:1px solid #a4b39b;border-radius:50%;font:12px Georgia,serif;background:#faf8f2c0}
.pin-caption{position:absolute;z-index:3;bottom:94px;left:62%;transform:translateX(-50%);max-width:300px;padding:10px 16px;border:1px solid var(--line);border-radius:10px;background:var(--paper);box-shadow:0 3px 16px #213b3210;text-align:center;font-size:14px;pointer-events:none}.pin-caption small{display:block;font-size:11px;color:var(--muted);margin-top:3px}
#toast{position:absolute;z-index:20;top:88px;left:50%;transform:translateX(-50%);max-width:90%;background:var(--green);color:var(--paper);font-size:13px;padding:12px 18px;border-radius:8px}
@media(hover:hover) and (pointer:fine){
 .action:hover{background:#42634d}.action.secondary:hover,.service-entry:hover{background:#dfe8d5}
 #categories button:not([aria-pressed=true]):hover,.side-tools button:hover,.view-dock button:not([aria-pressed=true]):hover{background:#e7ecdf}
 .place-row:hover,.history-row:hover{background:#eef1e7}.text-button:hover{color:#507246}
}
@media(min-width:801px) and (max-width:1100px){
 .masthead{inset:20px 20px auto}.brand{font-size:19px}.brand small{font-size:10px}.brand-symbol{width:36px;height:42px}
 .search-dock{top:20px;width:39vw}.header-actions>button,.settings>summary{padding:9px 10px;font-size:12px}
 .panel,.intro{width:320px;left:98px}#categories{left:18px}.view-dock{left:62%}.map-note{max-width:260px;font-size:10px}
}
@media(max-width:800px){
 .masthead{inset:10px 12px auto}.brand{font-size:17px;gap:8px;letter-spacing:1px;padding:3px 9px 3px 5px;border-radius:8px}.brand-symbol{width:25px;height:30px;font-size:21px;border-radius:10px 10px 3px 3px}.brand small{display:none}
 .header-actions{padding:0;border:0;background:#faf8f2e8}.header-actions>button,.settings>summary{min-height:36px;font-size:12px;padding:8px 10px}.settings-body{top:44px;width:245px}
 .search-dock{top:64px;left:12px;right:12px;width:auto;transform:none}.ask{padding:5px 6px 5px 13px;gap:9px;border-radius:10px}.ask input{font-size:14px;height:36px}.ask button{width:34px;height:34px}
 #categories{top:120px;left:12px;right:12px;width:auto;max-height:none;flex-direction:row;gap:2px;padding:4px;border-radius:10px;overflow:auto}
 #categories button{flex:1;min-width:0;min-height:36px;flex-direction:row;font-size:12px;padding:0 5px;border-radius:6px}#categories button svg{display:none}
 .intro{top:auto;bottom:96px;left:12px;right:12px;width:auto;padding:20px 22px}.intro h1{font-size:25px;line-height:1.4;margin:0 0 8px}.intro h1 br{display:none}.intro-copy{font-size:13px}.intro-copy br{display:none}.intro .eyebrow{font-size:11px;margin-bottom:8px}.intro-actions{margin-top:16px}.intro-hint{display:none}.intro-ornament{width:115px;height:145px}
 .panel{top:auto;left:10px;right:10px;bottom:94px;width:auto;max-height:min(36dvh,calc(100dvh - 282px));transform:translateY(10px);border-radius:16px}
 .panel[data-open=true]{transform:translateY(0)}.panel[data-view=list]{max-height:min(45dvh,calc(100dvh - 278px))}.panel[data-expanded=true]{max-height:calc(100dvh - 278px)}
 .panel-head{padding:16px 18px 12px;gap:8px}.panel-head h2,.panel[data-view=building] .panel-head h2{font-size:23px;line-height:1.45}.panel-head .eyebrow{font-size:11px;margin-bottom:4px}
 #panel-size{display:block;width:auto;padding:0 8px;font-size:12px}#panel-body{padding:16px 18px 20px}.panel-controls button{height:36px}
 .building-intro{margin-bottom:16px}.building-section h3{font-size:13px}.service-entry{padding:12px}.action-row{margin-top:16px}.source-details{margin-top:12px}
 .side-tools{bottom:102px;right:12px;flex-direction:row}.side-tools button{width:36px;height:38px}body[data-panel=open] .side-tools{display:none}
 .scene-footer{left:12px;right:12px;bottom:10px}.view-dock{bottom:25px;left:50%;width:max-content;max-width:100%;padding:4px;gap:1px;border-radius:10px}.view-dock button{font-size:12px;padding:8px 11px;min-height:38px}.divider{margin:0 3px}
 .map-note{padding:0;background:none;font-size:10px;max-width:78%}.map-note #scene-status{display:none}.map-note small{font-size:10px}.compass{display:none}.footer-right a{font-size:7px;margin:0}
 .pin-caption{top:178px;bottom:auto;left:50%;max-width:calc(100% - 40px);font-size:13px;padding:6px 12px}.pin-caption small{font-size:11px}#toast{top:172px}
}
@media(max-width:360px){.view-dock button{padding:8px}.header-actions>button{display:none}.panel-head h2{font-size:21px}.action-row{gap:8px}}
@media(max-height:650px) and (min-width:801px){#categories button{min-height:43px}#categories{gap:1px;top:100px}.panel,.intro{top:100px;max-height:calc(100dvh - 190px)}.side-tools{bottom:120px}}
@media(max-height:650px) and (max-width:800px){.panel{max-height:calc(100dvh - 300px)}.panel[data-expanded=true]{max-height:calc(100dvh - 264px)}.intro{padding:16px 20px}.intro-copy{display:none}}
.keyboard *{transition-duration:0s!important;animation:none!important}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{transition:none!important;animation:none!important;scroll-behavior:auto!important}}
